import { useEffect, useState } from 'react';

import { FileViewer } from '@/components/file/file-viewer';
import { Button } from '@/components/ui/button';

import {
  commands,
  type ArchiApiFinding,
  type ArchiApiRef,
  type ArchiElement,
  type ArchiModuleDetail,
  type ArchiRelation,
  type GateTier,
} from '../../../types/generated/bindings';
import { useArchiModule } from '../hooks/use-archi-module';

/** gate 三档（封闭值域；文案 = 线格式词）。 */
const GATE_TIERS: GateTier[] = ['off', 'warn', 'strict'];

/** 线值 → 档位收窄（类型守卫；词汇外即不认——不靠断言，UI 不作非法取值）。 */
function asGateTier(value: string): GateTier | null {
  return GATE_TIERS.find((tier) => tier === value) ?? null;
}

export type CanvasMode = 'full' | 'incremental';

export interface ElementDrawerProps {
  /** 观察根（当前工作根；`null` 时取数不发起） */
  root: string | null;
  /** 能力差异：`full` 只读 / `incremental` 可改档 */
  mode: CanvasMode;
  /** 当前聚焦元素 */
  element: ArchiElement | null;
  /** 图关系（`exempt` 边的 reason 行数据源） */
  relations: ArchiRelation[];
  /** 契约判据（父级同一份漂移报告，零新 invoke） */
  findings: ArchiApiFinding[];
  /** 改档成功后的父级重取（图与抽屉同步刷新） */
  onChanged: () => void;
}

/** 概览行（`modelFile:line` 行号未知时只渲文件）。 */
function Overview({ element }: { element: ArchiElement }): React.JSX.Element {
  const position =
    element.modelLine === 0 ? element.modelFile : `${element.modelFile}:${element.modelLine}`;
  return (
    <div className="flex flex-col gap-0.5 text-[13px]">
      <div className="break-all font-medium" data-testid="archi-drawer-fqn">
        {element.fqn}
      </div>
      <div className="text-muted-foreground">
        kind {element.kind} · gate {element.gate}
      </div>
      <div className="break-all text-muted-foreground">
        {element.path.length === 0 ? 'path （未声明）' : `path ${element.path.join('、')}`}
      </div>
      <div
        className="break-all font-mono text-xs text-muted-foreground"
        data-testid="archi-drawer-position"
      >
        {position}
      </div>
      {element.summary !== null && (
        <div className="wrap-break-word text-muted-foreground">{element.summary}</div>
      )}
    </div>
  );
}

/** 文档条目：展开 ADR 才取正文（越界 / 读盘失败行内呈现）。 */
function DocRow({
  root,
  path,
  title,
  source,
  kind,
}: {
  root: string;
  path: string;
  title: string;
  source: string;
  kind: string;
}): React.JSX.Element {
  return (
    <div className="flex flex-col gap-0.5" data-testid="archi-doc-item" data-source={source}>
      <FileViewer
        root={root}
        files={[{ path }]}
        trigger={
          <Button
            variant="ghost"
            size="sm"
            className="justify-start"
            disabled={kind !== 'adr'}
            title={path}
          >
            {title}
            <span className="ml-1 text-xs text-muted-foreground">
              {source} · {kind}
            </span>
          </Button>
        }
      />
    </div>
  );
}

/** 改档入口（`incremental` 才有；写命令 + 成功重取 + 失败行内错误）。 */
function GateEditor({
  root,
  element,
  onChanged,
}: {
  root: string | null;
  element: ArchiElement;
  onChanged: () => void;
}): React.JSX.Element {
  const [draft, setDraft] = useState<GateTier>(element.gate);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  // 权威档位一变即重取草稿：草稿是「待提交的本地意图」，MUST NOT 跨元素存活——
  // 否则切换聚焦元素后的「写回」会把上一个元素的档位写到新元素（父级重取回来的
  // 新档位同理）
  useEffect(() => {
    setDraft(element.gate);
    setError(null);
  }, [element.gate]);
  const submit = (): void => {
    if (root === null) {
      setError('无工作根，无法改档');
      return;
    }
    setSaving(true);
    setError(null);
    commands
      .archiSetGate(root, element.fqn, draft)
      .then(() => {
        setSaving(false);
        onChanged();
      })
      .catch((reason: unknown) => {
        setSaving(false);
        setError(String(reason));
      });
  };
  return (
    <div className="mt-2 flex flex-col gap-1">
      <div className="flex items-center gap-2">
        <label className="text-xs text-muted-foreground" htmlFor="archi-gate-select">
          改档
        </label>
        <select
          id="archi-gate-select"
          className="h-8 rounded-md border border-border bg-background px-2 text-sm"
          data-testid="archi-gate-select"
          value={draft}
          onChange={(event) => {
            const next = asGateTier(event.target.value);
            if (next !== null) setDraft(next);
          }}
        >
          {GATE_TIERS.map((tier) => (
            <option key={tier} value={tier}>
              {tier}
            </option>
          ))}
        </select>
        <Button disabled={saving} onClick={submit} data-testid="archi-gate-submit">
          写回
        </Button>
      </div>
      {error !== null && (
        <div
          className="break-all rounded-md bg-fail-bg px-2 py-1 text-xs text-fail"
          data-testid="archi-gate-error"
        >
          {error}
        </div>
      )}
    </div>
  );
}

/**
 * 契约段的一条路径行（`status = declared` 才渲；「查看」经通用 `read_file`）。
 * 路径为 `null` 时行仍渲、「查看」禁用：行数是「declared 三行」的契约面，缺席由
 * 禁用态呈现，MUST NOT 静默少渲一行。
 */
function ContractPathRow({
  root,
  label,
  path,
}: {
  root: string;
  label: string;
  path: string | null;
}): React.JSX.Element {
  return (
    <div
      className="flex items-center gap-1"
      data-testid="archi-contract-path"
      title={path ?? undefined}
    >
      <span className="shrink-0 text-xs text-muted-foreground">{label}</span>
      <span className="min-w-0 flex-1 truncate font-mono text-[11px] text-muted-foreground">
        {path ?? '（该路径未生成）'}
      </span>
      {path === null ? (
        // 路径缺席不吞行：行仍在场、「查看」禁用——`declared` 却缺路径的缺口要一眼可见
        <Button variant="ghost" size="sm" disabled>
          查看
        </Button>
      ) : (
        <FileViewer
          root={root}
          files={[{ path }]}
          trigger={
            <Button variant="ghost" size="sm">
              查看
            </Button>
          }
        />
      )}
    </div>
  );
}

/** 契约段（概览与文档之间）：`api.status` + 三路径行 + 本元素判据。 */
function ContractSection({
  root,
  element,
  api,
  findings,
}: {
  root: string | null;
  element: ArchiElement;
  api: ArchiApiRef;
  findings: ArchiApiFinding[];
}): React.JSX.Element {
  const own = findings.filter((finding) => finding.element === element.fqn);
  return (
    <div className="flex flex-col gap-1">
      <h3 className="m-0 text-[13px] font-medium text-muted-foreground">契约</h3>
      {api.status === 'none' || root === null ? (
        <div
          className="text-[13px] text-muted-foreground"
          data-testid="archi-contract-drawer-empty"
        >
          无契约（`api = none` 或契约文件不在案）
        </div>
      ) : (
        <>
          <div className="text-xs text-muted-foreground">api {api.status}</div>
          <ContractPathRow label="契约" path={api.contractPath} root={root} />
          <ContractPathRow label="schema" path={api.schemaPath} root={root} />
          <ContractPathRow label="生成物" path={api.generatedPath} root={root} />
          {own.length === 0 ? (
            <div
              className="text-[13px] text-muted-foreground"
              data-testid="archi-contract-drawer-empty"
            >
              本元素无漂移
            </div>
          ) : (
            own.map((finding, index) => (
              <div
                className="flex flex-col gap-0.5"
                data-kind={finding.kind}
                key={`${finding.kind}:${finding.target ?? ''}:${index}`}
              >
                <span className="text-[11px] text-muted-foreground">
                  {finding.kind}
                  {finding.target === null ? '' : ` · ${finding.target}`}
                </span>
                <span className="wrap-break-word text-xs">{finding.message}</span>
              </div>
            ))
          )}
        </>
      )}
    </div>
  );
}

/** 文档关联段（四字段条目按强度序；ADR 条目展开才取正文）。 */
function DocsSection({
  root,
  docs,
}: {
  root: string;
  docs: ArchiModuleDetail['docs'];
}): React.JSX.Element {
  return (
    <div className="flex flex-col gap-1">
      <h3 className="m-0 text-[13px] font-medium text-muted-foreground">文档</h3>
      {docs.length === 0 ? (
        <div className="text-[13px] text-muted-foreground" data-testid="archi-docs-empty">
          无关联文档
        </div>
      ) : (
        docs.map((doc) => (
          <DocRow
            key={doc.path}
            path={doc.path}
            title={doc.title}
            source={doc.source}
            kind={doc.kind}
            root={root}
          />
        ))
      )}
    </div>
  );
}

/** 豁免段（`exempt` 边的 reason 行；无豁免即整段隐藏）。 */
function ExemptSection({
  element,
  relations,
}: {
  element: ArchiElement;
  relations: ArchiRelation[];
}): React.JSX.Element | null {
  const exempt = relations.filter(
    (relation) =>
      relation.reason !== null && (relation.from === element.fqn || relation.to === element.fqn),
  );
  if (exempt.length === 0) return null;
  return (
    <div className="flex flex-col gap-0.5">
      <h3 className="m-0 text-[13px] font-medium text-muted-foreground">豁免</h3>
      {exempt.map((relation) => (
        <div
          className="break-all text-xs text-muted-foreground"
          data-testid="archi-exempt-reason"
          key={`${relation.from}->${relation.to}`}
        >
          {relation.from} → {relation.to}：{relation.reason}
        </div>
      ))}
    </div>
  );
}

/**
 * 右抽屉：概览 → 契约 → 文档关联 → 豁免 →（`incremental`）改档入口 /（`full`）只读
 * 提示。未选中元素时呈空态（不发 `archi_module` 取数）；契约段数据全部来自既有
 * `ArchiModuleDetail.api` 与父级同一份判据（零新 invoke）。
 */
export function ElementDrawer({
  root,
  mode,
  element,
  relations,
  findings,
  onChanged,
}: ElementDrawerProps): React.JSX.Element {
  const module = useArchiModule(root, element === null ? null : element.fqn);
  if (element === null) {
    return (
      <aside
        className="min-h-0 w-72 shrink-0 overflow-auto border-l border-border pl-2"
        data-testid="archi-drawer"
      >
        <div className="text-[13px] text-muted-foreground">未选中元素</div>
      </aside>
    );
  }
  return (
    <aside
      className="flex min-h-0 w-72 shrink-0 flex-col gap-2 overflow-auto border-l border-border pl-2"
      data-testid="archi-drawer"
    >
      <Overview element={element} />
      {module.error !== null && (
        <div
          className="break-all rounded-md bg-fail-bg px-2 py-1 text-xs text-fail"
          data-testid="archi-drawer-error"
        >
          {module.error}
        </div>
      )}
      {root !== null && module.detail !== null && (
        <ContractSection
          root={root}
          element={element}
          api={module.detail.api}
          findings={findings}
        />
      )}
      {root && <DocsSection root={root} docs={module.detail?.docs ?? []} />}
      <ExemptSection element={element} relations={relations} />
      {mode === 'incremental' ? (
        <GateEditor key={element.fqn} root={root} element={element} onChanged={onChanged} />
      ) : (
        <div className="mt-2 text-xs text-muted-foreground" data-testid="archi-gate-readonly">
          改档需要开一个 change（本页为只读视图）
        </div>
      )}
    </aside>
  );
}

src/views/architecture/components/file-t.source:
/**
 * 左栏文件树 + 分段控件。
 *
 * 数据面为后端扁平条目（`path` 字节序），层级 / 兄弟序 / 缩进全由本件按 `path` 派生
 * （目录先于文件、各自按 `name` 序）；展开态为 per-path 翻转集合、折叠不渲子树 DOM。
 * 五种归属标记只表达归属，MUST NOT 承载漂移违例 / 门禁 / 契约状态。数据面与信息页的
 * 目录树不同（marks / owners 对行数聚合），故不与之抽公共件。
 */

import { ChevronDown, ChevronRight, FileText, FolderClosed } from 'lucide-react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { ScrollArea } from '@/components/ui/scroll-area';

import type { ArchiFileEntry } from '../../../types/generated/bindings';

/** 默认展开层级：相对路径段数 ≤ 2 的目录默认展开（更深层默认折叠）。 */
const DEFAULT_EXPAND_SEGMENTS = 2;

/** 每层级缩进宽度（px）。 */
const INDENT_STEP = 16;

/** 左栏树视图（分段控件的三值；缺省 `file`）。 */
export type TreeMode = 'file' | 'element' | 'contract';

export interface FileTreeProps {
  /** 后端扁平条目（`path` 字节序；层级由本件按 `path` 派生） */
  entries: ArchiFileEntry[];
  /** 当前聚焦元素 FQN（`owners` 含它的条目高亮） */
  focused: string | null;
  /** 聚焦切换（纯前端，零取数） */
  onFocus: (fqn: string) => void;
}

export interface TreeModeSwitchProps {
  /** 当前左栏视图 */
  mode: TreeMode;
  /** 视图切换（只换左栏组件，`focus` 共用） */
  onChange: (mode: TreeMode) => void;
}

/** 派生森林节点（文件内形态，不导出）。 */
interface FileTreeNode {
  entry: ArchiFileEntry;
  children: FileTreeNode[];
}

/** 扁平条目 → 森林：按 `path` 切段挂父（父缺席的条目挂根）。 */
function buildForest(entries: ArchiFileEntry[]): FileTreeNode[] {
  const byPath = new Map<string, FileTreeNode>();
  for (const entry of entries) byPath.set(entry.path, { entry, children: [] });
  const roots: FileTreeNode[] = [];
  for (const node of byPath.values()) {
    const cut = node.entry.path.lastIndexOf('/');
    const parent = cut < 0 ? undefined : byPath.get(node.entry.path.slice(0, cut));
    if (parent === undefined) roots.push(node);
    else parent.children.push(node);
  }
  const sortSiblings = (nodes: FileTreeNode[]): void => {
    nodes.sort((left, right) => {
      const leftRank = left.entry.kind === 'dir' ? 0 : 1;
      const rightRank = right.entry.kind === 'dir' ? 0 : 1;
      if (leftRank !== rightRank) return leftRank - rightRank;
      return left.entry.name.localeCompare(right.entry.name);
    });
    for (const node of nodes) sortSiblings(node.children);
  };
  sortSiblings(roots);
  return roots;
}

/** 展开态判定：聚焦命中的祖先链强制展开优先，其次 per-path 翻转，最后默认前 2 段。 */
function isExpanded(
  path: string,
  flipped: ReadonlySet<string>,
  forcedOpen: ReadonlySet<string>,
): boolean {
  if (forcedOpen.has(path)) return true;
  const byDefault = path.split('/').length <= DEFAULT_EXPAND_SEGMENTS;
  return flipped.has(path) ? !byDefault : byDefault;
}

/** 归属标记（图标 + 色 + tooltip 按词表五值；`none` 无标记零 tooltip）。 */
function MarkBadge({ entry }: { entry: ArchiFileEntry }): React.JSX.Element | null {
  const owner = entry.owners[0];
  switch (entry.mark) {
    case 'elementRoot':
      return (
        <span
          className="shrink-0 rounded-full bg-primary size-2"
          data-mark={entry.mark}
          data-testid="archi-file-mark"
          title={`模块 ${owner ?? ''}`}
        />
      );
    case 'ambiguous':
      return (
        <span
          className="shrink-0 rounded-full bg-warn size-2"
          data-mark={entry.mark}
          data-testid="archi-file-mark"
          title={`多归属：${entry.owners.join('、')}`}
        />
      );
    case 'member':
      return (
        <span
          className="h-3 shrink-0 border-l-2 border-muted-foreground/60"
          data-mark={entry.mark}
          data-testid="archi-file-mark"
          title={`属于 ${owner ?? ''}`}
        />
      );
    case 'containsElements':
      return (
        <span className="flex shrink-0 items-center gap-1">
          <span
            className="rounded-full border border-muted-foreground size-2"
            data-mark={entry.mark}
            data-testid="archi-file-mark"
            title={`含 ${entry.contains} 个模块`}
          />
          <span className="text-[11px] tabular-nums text-muted-foreground">·{entry.contains}</span>
        </span>
      );
    case 'none':
      return null;
  }
}

interface RowContext {
  focused: string | null;
  flipped: ReadonlySet<string>;
  forcedOpen: ReadonlySet<string>;
  onToggle: (path: string) => void;
  onFocus: (fqn: string) => void;
  refOf: (path: string) => (element: HTMLDivElement | null) => void;
}

/** 行名样式（按词表五值：`elementRoot` / `ambiguous` 加粗、`member` 弱化、其余常规）。 */
function nameClass(mark: ArchiFileEntry['mark']): string {
  switch (mark) {
    case 'elementRoot':
      return 'font-medium text-primary';
    case 'ambiguous':
      return 'font-medium text-warn';
    case 'member':
      return 'text-muted-foreground';
    default:
      return '';
  }
}

/** 单条目行（递归渲染子树）：归属行整行点击圈定范围，其余标记只切展开（chevron 与
 * 整行同语义，故在 chevron 上阻断冒泡以免触发两次翻转）。 */
function FileRow({
  node,
  level,
  context,
}: {
  node: FileTreeNode;
  level: number;
  context: RowContext;
}): React.JSX.Element {
  const { entry, children } = node;
  const expanded = isExpanded(entry.path, context.flipped, context.forcedOpen);
  const hasChildren = children.length > 0;
  const owned = entry.mark === 'elementRoot' || entry.mark === 'member';
  const focused = context.focused !== null && entry.owners.includes(context.focused);
  const toggle = (): void => context.onToggle(entry.path);
  const activate = (): void => {
    if (owned) {
      const owner = entry.owners[0];
      if (owner !== undefined) context.onFocus(owner);
      return;
    }
    if (hasChildren) toggle();
  };
  return (
    <>
      <div
        className={`flex items-center gap-1 rounded-md py-0.5 pr-2 hover:bg-muted ${owned || hasChildren ? 'cursor-pointer' : ''} ${focused ? 'bg-muted' : ''}`}
        data-mark={entry.mark}
        data-path={entry.path}
        data-testid="archi-file-node"
        onClick={activate}
        ref={context.refOf(entry.path)}
        style={{ paddingLeft: 8 + level * INDENT_STEP }}
        title={entry.path}
      >
        {hasChildren ? (
          <button
            type="button"
            aria-expanded={expanded}
            aria-label={`${expanded ? '收起' : '展开'} ${entry.path}`}
            className="shrink-0 cursor-pointer border-0 bg-transparent p-0 text-muted-foreground"
            onClick={(event) => {
              event.stopPropagation();
              toggle();
            }}
          >
            {expanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
          </button>
        ) : (
          <span className="w-[14px] shrink-0" />
        )}
        <span className="flex min-w-0 flex-1 items-center gap-1.5 text-left">
          {entry.kind === 'dir' ? (
            <FolderClosed className="shrink-0 text-muted-foreground" size={14} />
          ) : (
            <FileText className="shrink-0 text-muted-foreground" size={14} />
          )}
          <span className={`truncate text-sm ${nameClass(entry.mark)}`}>{entry.name}</span>
          {entry.exists ? null : (
            <span className="shrink-0 text-[11px] text-fail" title="声明了但磁盘上不存在">
              缺失
            </span>
          )}
          <MarkBadge entry={entry} />
        </span>
      </div>
      {expanded && hasChildren
        ? children.map((child) => (
            <FileRow context={context} key={child.entry.path} level={level + 1} node={child} />
          ))
        : null}
    </>
  );
}

/** 聚焦反查（纯派生，零 state 写入）：`owners` 含该 FQN 的条目即命中（多 `path`
 * 元素会有多条命中），祖先链强制展开（用户翻转态不被覆盖），并滚动到首条。 */
function useFocusAnchors(
  entries: ArchiFileEntry[],
  focused: string | null,
): { hitPaths: string[]; forcedOpen: ReadonlySet<string>; refOf: RowContext['refOf'] } {
  const nodes = useRef<Map<string, HTMLDivElement>>(new Map());
  const hitPaths = useMemo(
    () =>
      focused === null
        ? []
        : entries.filter((entry) => entry.owners.includes(focused)).map((entry) => entry.path),
    [entries, focused],
  );
  const forcedOpen = useMemo(() => {
    const open = new Set<string>();
    for (const hit of hitPaths) {
      const segments = hit.split('/');
      for (let index = 1; index < segments.length; index += 1) {
        open.add(segments.slice(0, index).join('/'));
      }
    }
    return open;
  }, [hitPaths]);
  const refOf = useCallback(
    (path: string) =>
      (element: HTMLDivElement | null): void => {
        if (element === null) nodes.current.delete(path);
        else nodes.current.set(path, element);
      },
    [],
  );
  useEffect(() => {
    const first = hitPaths[0];
    if (first === undefined) return;
    nodes.current.get(first)?.scrollIntoView?.({ block: 'nearest' });
  }, [hitPaths]);
  return { hitPaths, forcedOpen, refOf };
}

/** 树底部可折叠图例（说明树面 = 判定面）。 */
function Legend({ open, onToggle }: { open: boolean; onToggle: () => void }): React.JSX.Element {
  return (
    <div
      className="mt-1 shrink-0 text-[11px] text-muted-foreground"
      data-testid="archi-file-tree-legend"
    >
      <button
        type="button"
        aria-expanded={open}
        className="cursor-pointer border-0 bg-transparent p-0 text-[11px] text-muted-foreground hover:text-foreground"
        onClick={onToggle}
      >
        图例
      </button>
      {open ? (
        <div className="mt-0.5 leading-snug">
          仅显示判定面源文件（测试文件与架构配置 exclude 命中项不在树中；none 行 = 无元素认领）
        </div>
      ) : null}
    </div>
  );
}

/** 左栏文件树：数据面为后端扁平条目，层级 / 兄弟序 / 缩进与展开态全由本件派生。 */
export function FileTree({ entries, focused, onFocus }: FileTreeProps): React.JSX.Element {
  const [flipped, setFlipped] = useState<ReadonlySet<string>>(() => new Set());
  const [legendOpen, setLegendOpen] = useState(false);
  const onToggle = useCallback((path: string) => {
    setFlipped((prev) => {
      const next = new Set(prev);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });
  }, []);
  const forest = useMemo(() => buildForest(entries), [entries]);
  const { hitPaths, forcedOpen, refOf } = useFocusAnchors(entries, focused);
  const context: RowContext = { focused, flipped, forcedOpen, onToggle, onFocus, refOf };
  return (
    <section className="min-h-0 flex flex-1 flex-col" data-testid="archi-file-tree">
      <h2 className="m-0 mb-1.5 text-[13px] shrink-0 font-medium text-muted-foreground">文件</h2>
      {focused !== null && hitPaths.length === 0 ? (
        <div
          className="mb-1.5 text-[11px] text-muted-foreground"
          data-testid="archi-file-tree-focus-miss"
        >
          该元素在树上无可定位节点（容器元素不持有文件，或其源文件均在判定面之外）
        </div>
      ) : null}
      {entries.length === 0 ? (
        <div className="text-[13px] text-muted-foreground" data-testid="archi-file-tree-empty">
          仓库内无源文件
        </div>
      ) : (
        <ScrollArea className="flex-1 min-h-0 pr-2">
          {forest.map((node) => (
            <FileRow context={context} key={node.entry.path} level={0} node={node} />
          ))}
        </ScrollArea>
      )}
      <Legend open={legendOpen} onToggle={() => setLegendOpen((open) => !open)} />
    </section>
  );
}

/**
 * 左栏视图分段控件（缺省「文件」；三视图 = 文件 / 元素 / 契约）。文件 / 元素两视图的
 * 分段语义与联动逐字不变，契约视图的内容归 `ContractPanel`。
 */
export function TreeModeSwitch({ mode, onChange }: TreeModeSwitchProps): React.JSX.Element {
  const options: { mode: TreeMode; label: string }[] = [
    { mode: 'file', label: '文件' },
    { mode: 'element', label: '元素' },
    { mode: 'contract', label: '契约' },
  ];
  return (
    <div className="mb-1.5 flex shrink-0 gap-1" data-testid="archi-tree-mode" role="group">
      {options.map((option) => (
        <button
          key={option.mode}
          type="button"
          aria-pressed={mode === option.mode}
          className={`cursor-pointer rounded-md border px-2 py-0.5 text-[11px] ${
            mode === option.mode
              ? 'border-primary/40 bg-muted font-medium text-foreground'
              : 'border-transparent bg-transparent text-muted-foreground hover:text-foreground'
          }`}
          data-mode={option.mode}
          onClick={() => onChange(option.mode)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}

src/views/architecture/components/archit.source:
import {
  Handle,
  Position,
  ReactFlow,
  ReactFlowProvider,
  type Edge,
  type Node,
  type NodeProps,
} from '@xyflow/react';
import { useMemo, useState } from 'react';

import '@xyflow/react/dist/style.css';

import { Badge } from '@/components/ui/badge';
import type {
  ArchiApiFinding,
  ArchiElement,
  ArchiFileTree,
  ArchiGraph,
  ArchiRelation,
} from '@/types/generated/bindings';

import { useArchiDrift } from '../hooks/use-archi-drift';
import { useArchiFileTree } from '../hooks/use-archi-file-tree';
import { useArchiGraph } from '../hooks/use-archi-graph';
import { driftMarks } from '../lib/drift-marks';
import { shortName } from '../lib/fqn';
import { edgeVisual } from '../lib/marks';
import { ContractPanel } from './contract-panel';
import { ElementDrawer, type CanvasMode } from './element-drawer';
import { ElementTree } from './element-tree';
import { FileTree, TreeModeSwitch, type TreeMode } from './file-tree';
import { StructureErrorPanel } from './structure-error-panel';

/** 邻域布局网格步长（纯拓扑定位，不引布局引擎）。 */
const STEP_X = 240;
const STEP_Y = 96;

/** 初视口适配全图：留边距，单节点不过度放大。 */
const FIT_VIEW_OPTIONS = { padding: 0.2, minZoom: 0.2, maxZoom: 1 };

export interface ArchitectureCanvasProps {
  /** 观察根（`null` = 壳态无根：不发起取数） */
  root: string | null;
  /** 能力差异：`full` 全量只读 / `incremental` 增量可改档 */
  mode: CanvasMode;
}

type ArchiNodeData = { label: string; mark: string };

type ArchiFlowNode = Node<ArchiNodeData, 'archi'>;

/** 隐形把手（连线锚点：入边左 / 出边右）；xyflow 无把手即不求边位置，边不入 DOM。 */
function NodeHandles(): React.JSX.Element {
  const rounded = {
    width: '100%',
    height: '100%',
    top: 0,
    left: 0,
    opacity: 0,
    transform: 'none',
  };
  return (
    <>
      <Handle type="target" position={Position.Left} isConnectable={false} style={rounded} />
      <Handle type="source" position={Position.Right} isConnectable={false} style={rounded} />
    </>
  );
}

/** 节点视图（本文件内局部组件——不为单节点单建文件）。 */
function ArchiNodeView({ data }: NodeProps<ArchiFlowNode>): React.JSX.Element {
  return (
    <Badge variant="secondary" className="p-3" data-testid="archi-canvas-node">
      <NodeHandles />
      {data.label}
    </Badge>
  );
}

const nodeTypes = { archi: ArchiNodeView };

/** 缺省聚焦：首个顶层元素，无顶层则首个元素。 */
function defaultFocus(graph: ArchiGraph): string | null {
  const root = graph.elements.find((element) => !element.fqn.includes('.'));
  return root?.fqn ?? graph.elements[0]?.fqn ?? null;
}

/** 邻域坐标（纯函数）：聚焦居中、出边向右、入边向左、子元素下方（网格堆叠）。 */
function neighborhoodPositions(
  focus: string,
  outgoing: string[],
  incoming: string[],
  children: string[],
): Map<string, { x: number; y: number }> {
  const positions = new Map<string, { x: number; y: number }>();
  positions.set(focus, { x: 0, y: 0 });
  const place = (fqns: string[], x: number, y0: number): void => {
    fqns.forEach((fqn, index) => {
      positions.set(fqn, { x, y: y0 + index * STEP_Y });
    });
  };
  place(incoming, -STEP_X, -((incoming.length - 1) * STEP_Y) / 2);
  place(outgoing, STEP_X, -((outgoing.length - 1) * STEP_Y) / 2);
  place(children, 0, STEP_Y);
  return positions;
}

/** 邻域三项（与 `ModelGraph` 邻域查询同构：出边 / 入边 / 直接子元素）。 */
function neighborhood(
  graph: ArchiGraph,
  focus: string,
): { outgoing: string[]; incoming: string[]; children: string[] } {
  const outgoing = graph.relations
    .filter((relation) => relation.from === focus)
    .map((relation) => relation.to);
  const incoming = graph.relations
    .filter((relation) => relation.to === focus)
    .map((relation) => relation.from);
  const prefix = `${focus}.`;
  const children = graph.elements
    .filter(
      (element) =>
        element.fqn.startsWith(prefix) && !element.fqn.slice(prefix.length).includes('.'),
    )
    .map((element) => element.fqn);
  return { outgoing, incoming, children };
}

function toNodes(graph: ArchiGraph, focus: string): ArchiFlowNode[] {
  const { outgoing, incoming, children } = neighborhood(graph, focus);
  const positions = neighborhoodPositions(focus, outgoing, incoming, children);
  const members = new Set<string>([focus, ...outgoing, ...incoming, ...children]);
  const byFqn = new Map<string, ArchiElement>(
    graph.elements.map((element) => [element.fqn, element]),
  );
  const nodes: ArchiFlowNode[] = [];
  for (const fqn of members) {
    const element = byFqn.get(fqn);
    const position = positions.get(fqn);
    if (element === undefined || position === undefined) continue;
    nodes.push({
      id: fqn,
      type: 'archi',
      position,
      data: { label: shortName(fqn), mark: element.mark },
    });
  }
  return nodes;
}

function toEdges(graph: ArchiGraph, focus: string): Edge[] {
  return graph.relations
    .filter((relation) => relation.from === focus || relation.to === focus)
    .map((relation) => {
      const visual = edgeVisual(relation.mark);
      return {
        id: `${relation.from}->${relation.to}`,
        source: relation.from,
        target: relation.to,
        style: {
          stroke: visual.stroke,
          strokeDasharray: visual.dasharray ?? undefined,
        },
      };
    });
}

/** 左栏树栏位：分段控件 + 三态行（缺省文件树，可切元素树 / 契约视图）。切换只换左栏
 * 组件，`focus` 共用；取数失败只落本栏行内提示，画布与抽屉照常渲染。 */
function TreeColumn({
  root,
  canvasMode,
  mode,
  onModeChange,
  elements,
  focused,
  onFocus,
  tree,
  treeError,
  findings,
}: {
  root: string | null;
  canvasMode: CanvasMode;
  mode: TreeMode;
  onModeChange: (mode: TreeMode) => void;
  elements: ArchiElement[];
  focused: string | null;
  onFocus: (fqn: string) => void;
  tree: ArchiFileTree | null;
  treeError: string | null;
  findings: ArchiApiFinding[];
}): React.JSX.Element {
  return (
    <section className={`min-h-0 shrink-0 flex flex-col ${mode === 'element' ? 'w-72' : 'w-80'}`}>
      <TreeModeSwitch mode={mode} onChange={onModeChange} />
      <div className="min-h-0 flex-1 flex">
        {mode === 'contract' ? (
          <ContractPanel root={root} mode={canvasMode} findings={findings} onFocus={onFocus} />
        ) : mode === 'element' ? (
          <ElementTree elements={elements} focused={focused} onFocus={onFocus} />
        ) : treeError !== null ? (
          <div className="text-[13px] text-muted-foreground" data-testid="archi-file-tree-error">
            文件树取数失败：{treeError}（画布照常渲染）
          </div>
        ) : tree === null ? (
          <div className="text-[13px] text-muted-foreground" data-testid="archi-file-tree-loading">
            解析中…
          </div>
        ) : (
          <FileTree entries={tree.entries} focused={focused} onFocus={onFocus} />
        )}
      </div>
    </section>
  );
}

/** 空模型提示（结构性早退分支，画布零节点零边）。 */
function ModelEmptyNotice(): React.JSX.Element {
  return (
    <div className="text-[13px] text-muted-foreground" data-testid="archi-canvas-empty">
      模型为空：先在 change 的 dev-design 阶段生成骨架（新元素缺省 gate = off）。
    </div>
  );
}

/** 漂移取数失败行内提示（叠加信息，不阻断图）。 */
function DriftErrorNotice({ message }: { message: string }): React.JSX.Element {
  return (
    <div className="px-2 py-1 text-[11px] text-muted-foreground" data-testid="archi-drift-error">
      漂移取数失败：{message}（图照常渲染，零标记）
    </div>
  );
}

/** 正常态三段布局（左栏树——缺省文件树，可切元素树 / 画布 / 抽屉）。漂移取数失败时
 * 零标记照常渲染 + 画布区顶部一行内提示（叠加信息不阻断图）。 */
function CanvasBody({
  graph,
  root,
  mode,
  onChanged,
  driftError,
  apiFindings,
}: {
  graph: ArchiGraph;
  root: string | null;
  mode: CanvasMode;
  onChanged: () => void;
  driftError: string | null;
  apiFindings: ArchiApiFinding[];
}): React.JSX.Element {
  const [focusOverride, setFocusOverride] = useState<string | null>(null);
  const [treeMode, setTreeMode] = useState<TreeMode>('file');
  // 文件树取数：与图 / 漂移独立失败，失败只落左栏行内提示
  const { tree, error: treeError } = useArchiFileTree(root);
  const focus = useMemo(() => {
    if (focusOverride !== null && graph.elements.some((element) => element.fqn === focusOverride)) {
      return focusOverride;
    }
    return defaultFocus(graph);
  }, [graph, focusOverride]);
  const nodes = useMemo(() => (focus === null ? [] : toNodes(graph, focus)), [graph, focus]);
  const edges = useMemo(() => (focus === null ? [] : toEdges(graph, focus)), [graph, focus]);
  const focused =
    focus === null ? null : (graph.elements.find((element) => element.fqn === focus) ?? null);
  const relations: ArchiRelation[] = graph.relations;
  if (graph.elements.length === 0) {
    return <ModelEmptyNotice />;
  }
  return (
    <div className="flex h-full min-h-0 gap-2">
      <TreeColumn
        root={root}
        canvasMode={mode}
        mode={treeMode}
        onModeChange={setTreeMode}
        elements={graph.elements}
        focused={focus}
        onFocus={setFocusOverride}
        tree={tree}
        treeError={treeError}
        findings={apiFindings}
      />
      <div
        className="min-h-0 flex-1 overflow-hidden rounded-md bg-background"
        data-testid="archi-canvas"
      >
        {driftError === null ? null : <DriftErrorNotice message={driftError} />}
        <ReactFlow
          nodes={nodes}
          edges={edges}
          nodeTypes={nodeTypes}
          onNodeClick={(_event, node) => setFocusOverride(node.id)}
          nodesDraggable={false}
          nodesConnectable={false}
          fitView={true}
          fitViewOptions={FIT_VIEW_OPTIONS}
          zoomOnScroll={false}
          zoomOnDoubleClick={false}
          panOnScroll
        />
      </div>
      <ElementDrawer
        root={root}
        mode={mode}
        element={focused}
        relations={relations}
        findings={apiFindings}
        onChanged={onChanged}
      />
    </div>
  );
}

export function ArchitectureCanvas({ root, mode }: ArchitectureCanvasProps): React.JSX.Element {
  const { graph, loading, error, refresh } = useArchiGraph(root);
  // 漂移取数：与图同一观察根、模式随挂载点分流（`full` / `incremental`）；
  // 标记生产在 drift-marks 纯函数，本组件只做一行合并
  const { report, error: driftError } = useArchiDrift(root, mode);
  const marked = useMemo(
    () => (graph === null ? null : driftMarks(report, graph)),
    [graph, report],
  );
  if (loading && graph === null) {
    return (
      <div className="text-[13px] text-muted-foreground" data-testid="archi-canvas-loading">
        解析中…
      </div>
    );
  }
  if (error !== null) {
    return (
      <div
        className="break-all rounded-md bg-fail-bg px-3 py-2 text-[13px] text-fail"
        data-testid="archi-canvas-error"
      >
        {error}
      </div>
    );
  }
  if (graph === null || marked === null) {
    return (
      <div className="text-[13px] text-muted-foreground" data-testid="archi-canvas-empty">
        无工作区根：无法解析架构模型。
      </div>
    );
  }
  // 全或无停摆：任何结构错 ⇒ 只渲错误面板（零图数据、零降级样式）
  if (graph.diagnostics.length > 0) {
    return (
      <div data-testid="archi-canvas">
        <StructureErrorPanel diagnostics={graph.diagnostics} />
      </div>
    );
  }
  return (
    <ReactFlowProvider>
      <CanvasBody
        graph={marked}
        root={root}
        mode={mode}
        onChanged={refresh}
        driftError={driftError}
        apiFindings={report?.apiFindings ?? []}
      />
    </ReactFlowProvider>
  );
}

