    </MemoryRouter>,
  );
}

/** 已挂载详情页换根重渲染（根切换场景）：Router 实例保持、location 不重置。 */
function rerenderDetail(view: ReturnType<typeof renderDetail>, f: DetailFixture, root: string) {
  loadFixture(f);
