    renderDetail({ detail: detail(), artifacts: PROPOSAL_ENVELOPES });
    await act(async () => {});
    expect(ChannelMock.instances).toHaveLength(1);

    // 失败轮：detail / activeRun 保持 → activeRunPresent 真值 → 订阅不被拆
    await notifyAndFlush();
