  it('应在空条目时渲空树提示并零行节点', () => {
    renderTree([]);

    expect(screen.getByTestId('archi-file-tree-empty').textContent).toBe('仓库内无源文件');
    expect(screen.queryAllByTestId('archi-file-node')).toHaveLength(0);
  });
});

